/* the image whose key is nearest to `key` */
static const lv_image_dsc_t *img_pick(const lv_image_dsc_t *img, const uint8_t *k, int n, int32_t key)
{
    int best = 0;
    for (int i = 1; i < n; i++) {
        int32_t a = key - k[i], b = key - k[best];
        if ((a < 0 ? -a : a) < (b < 0 ? -b : b)) best = i;
    }
    return &img[best];
}

